Item.method_code:
const { getProps, getState, itemTypeName } = options;
const { favorite } = getProps();

if (favorite) {
	await aras.getMainWindow().ArasCore.Dialogs.openFavoriteDialog(favorite);
	return;
}

const { item } = getState();
const itemConfigId = item?.config_id ?? aras.getItemProperty(window.item, 'config_id');
const itemKeyedName = item?.keyed_name ?? aras.getItemProperty(window.item, 'keyed_name');
const { store } = await import('../jsBundles/store.es.js');
const system = store.getState().system;
const { defaultLanguageCode, languages } = system;
const aliasIdentityId = system.user.identityId;

const favoriteLocaleLabels =
	languages &&
	defaultLanguageCode &&
	languages.length > 1
		? languages.reduce((acc, { code }) => {
				if (code !== defaultLanguageCode) {
					acc[`label@aras.lang.${code}`] = itemKeyedName;
				}
				return acc;
			}, {})
		: {};

const newFavorite = {
	'@action': 'add',
	category: 'Item',
	contextType: itemTypeName,
	label: itemKeyedName,
	ownedBy: aliasIdentityId,
	additional_data: {id: itemConfigId},
	quickAccessFlag: '1',
	...favoriteLocaleLabels
};

return aras.getMainWindow().ArasCore.Dialogs.openFavoriteDialog(newFavorite);
